def reverse_string(s):
    stack = []
    for ch in s:
        stack.append(ch)
    out = ''
    while stack:
        out += stack.pop()
    return out

def balanced(s):
    stack = []
    for ch in s:
        if ch == '(':
            stack.append(ch)
        elif ch == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

