from collections import deque

def bfs_order(graph, start):
    seen = {start}
    q = deque([start])
    order = []
    while q:
        node = q.popleft()
        order.append(node)
        for nb in graph[node]:
            if nb not in seen:
                seen.add(nb)
                q.append(nb)
    return order

def dfs_order(graph, start):
    seen = set()
    order = []
    def go(n):
        seen.add(n)
        order.append(n)
        for nb in graph[n]:
            if nb not in seen:
                go(nb)
    go(start)
    return order
